package com.crypto.laplace.service;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import com.crypto.common.enums.PositionSide;import com.crypto.domain.model.Kline;import com.crypto.laplace.config.LaplaceStrategyProperties;import com.crypto.laplace.model.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;
class LaplaceEntryDecisionServiceTest {
 @Test void rejectsHistoryWhoseLastCandleDoesNotReachSignalCutoff(){var klines=mock(FiveMinuteKlineService.class);var vp=mock(LaplaceVolumeProfileCalculator.class);var properties=new LaplaceStrategyProperties();Instant cutoff=Instant.parse("2026-08-06T10:30:00Z");List<Kline> history=new ArrayList<>();for(int i=0;i<500;i++){Instant close=cutoff.minusSeconds((500L-i)*300);history.add(Kline.builder().closeTime(close).close(BigDecimal.valueOf(100)).low(BigDecimal.valueOf(99)).high(BigDecimal.valueOf(101)).quoteAssetVolume(BigDecimal.ONE).build());}when(klines.loadLastClosedThrough("BTCUSDT",cutoff,500)).thenReturn(history);var decision=new LaplaceEntryDecisionService(klines,vp,properties).evaluate(signal(cutoff),PositionSide.LONG);assertThat(decision.allowed()).isFalse();assertThat(decision.rejectionReasons()).containsExactly(LaplaceEntryRejectionReason.FIVE_MINUTE_HISTORY_UNAVAILABLE);}
 private LaplaceSignalResult signal(Instant close){return new LaplaceSignalResult("LAPLACE_KERNEL_REGRESSION_30M","KURAL5_V1","BTCUSDT","30m","LAPLACE",14,"CLOSE",false,close.minusSeconds(1800),close,100,100,100,100,1,1,1,1,.01,.01,.03,.04,2,LaplaceSignal.SHORT,LaplaceSignal.NONE,StartupState.ACTIVE,1,true,List.of());}
}
